// ---- fabric families and weight bands: how the library is browsed ----
export const FABRIC_FAMILIES = [
  { id: 'jersey', label: 'Jersey and tee knits' }, { id: 'fleece', label: 'Fleece and terry' }, { id: 'knitwear', label: 'Knitwear and rib' },
  { id: 'shirting', label: 'Shirting cottons and linen' }, { id: 'bottomweight', label: 'Twills, chinos and cords' }, { id: 'denim', label: 'Denim' }, { id: 'canvas', label: 'Canvas and duck' },
  { id: 'technical', label: 'Outerwear and technical' }, { id: 'wool', label: 'Wool and tailoring' }, { id: 'leather', label: 'Leather' }, { id: 'vegan', label: 'Vegan leather' }, { id: 'other', label: 'Other' }
];
export function fabricFamily(m = {}) {
  const s = m.spec || {}, c = String(s.construction || '').toLowerCase(), comp = String(s.composition || '').toLowerCase();
  if (/pu leather|microfibre (leather|suede)|plant-based leather|mycelium|^cork|faux (suede|shearling|leather)|vegan/.test(c) || (/leather|suede/.test(c) && /\bpu\b|polyurethane|microfib/.test(comp))) return 'vegan';
  if (/leather|suede|nubuck|shearling/.test(c)) return 'leather';
  if (/denim/.test(c)) return 'denim';
  if (/fleece|terry|loopback|sherpa/.test(c)) return 'fleece';
  if (/gauge|knit \(jumper\)|merino|^rib/.test(c)) return 'knitwear';
  if (/jersey|interlock|piqu|waffle|tricot/.test(c)) return 'jersey';
  if (/ripstop|taslan|taffeta|nylon|softshell|pongee|cordura|mesh|stretch woven|shell|neoprene|scuba/.test(c) || (/oxford/.test(c) && /nylon|polyester/.test(comp))) return 'technical';
  if (/melton|tweed|boiled wool/.test(c) || (/flannel|herringbone/.test(c) && /wool/.test(comp))) return 'wool';
  if (/canvas|duck/.test(c)) return 'canvas';
  if (/twill shirting/.test(c)) return 'shirting';
  if (/twill|gabardine|drill|chino|corduroy|needlecord|moleskin|cavalry|herringbone|sateen|bedford/.test(c)) return 'bottomweight';
  if (/poplin|broadcloth|oxford|end-on-end|seersucker|voile|lawn|gauze|dobby|chambray|shirting|flannel|linen|batiste/.test(c)) return 'shirting';
  return 'other';
}
// light, mid or heavy for what it is: a shirting at 140 gsm is mid, a tee at 140 is light; leather by its thickness
export function weightBand(m = {}) {
  const s = m.spec || {}, f = fabricFamily(m), g = Number(s.weightGsm) || 0, t = Number(s.thicknessMm) || 0;
  if (f === 'leather' || f === 'vegan') return !t ? '' : t < .9 ? 'light' : t <= 1.4 ? 'mid' : 'heavy';
  if (!g) return '';
  const [a, b] = f === 'shirting' ? [100, 160] : f === 'jersey' ? [170, 240] : f === 'fleece' ? [300, 400] : f === 'denim' ? [340, 440] : f === 'technical' ? [120, 250] : [200, 330];
  return g < a ? 'light' : g <= b ? 'mid' : 'heavy';
}
export const WEIGHT_BANDS = [{ id: 'light', label: 'Light' }, { id: 'mid', label: 'Mid' }, { id: 'heavy', label: 'Heavy' }];
// a woven's weight as mills quote it in the US: ounces a square yard
export const ozOf = gsm => (gsm ? Math.round(gsm / 33.906 * 10) / 10 : 0);

